import java.util.Arrays;

public class ArrayBugsDemo {
    public static void main(String[] args) {
        // Bug 1: Aliasing mutation
        int[] a = {5, 10};
        int[] b = a;
        b[0] = 50;
        System.out.println("a[0] was mutated: " + a[0]); // 50

        // Bug 2: for-each mutation failure
        int[] c = {1, 2, 3};
        for (int x : c) x = 0;
        System.out.println("c array unchanged: " + Arrays.toString(c)); // [1, 2, 3]

        // Bug 3: Safe boundary check
        System.out.println("Last valid index of c is: " + (c.length - 1));
    }
}

