practiceProblems.solutionCode:
public class Main {
    public static void main(String[] args) {
        String[] names = new String[3];
        names[1] = "Sarah";
        for (int i = 0; i < names.length; i++) {
            if (names[i] != null) {
                System.out.println("Name: " + names[i]);
            } else {
                System.out.println("Slot Empty");
            }
        }
    }
}

