practiceProblems.solutionCode:
public class Main {
    public static int safeArrayLength(int[] arr) {
        if (arr == null) {
            return 0;
        }
        return arr.length;
    }

    public static void main(String[] args) {
        int len1 = safeArrayLength(null);
        int len2 = safeArrayLength(new int[]{1, 2, 3});
        System.out.println("Length of null: " + len1 + " | Length of data: " + len2);
    }
}

