practiceProblems.solutionCode:
import java.util.Arrays;

public class Main {
    public static void swapFirstTwo(int[] arr) {
        int temp = arr[0];
        arr[0] = arr[1];
        arr[1] = temp;
    }

    public static void main(String[] args) {
        int[] data = {10, 20, 30};
        swapFirstTwo(data);
        System.out.println("After swap: " + Arrays.toString(data));
    }
}
